init_mail();
async function runDaily(db, opts) {
  const started = performance.now();
  const asOf = opts.asOf ?? today();
  const actor2 = opts.actor ?? SYSTEM;
  const run = await db.prepare("INSERT INTO job_runs (job, triggered_by) VALUES ('daily', ?)").run(opts.trigger);
  const { billing: billing2 } = await getSettings(db);
  const out = { asOf, created: 0, closed: 0, confirmed: 0, sent: 0, reminders: 0, dunningClosed: 0, renewalReminders: 0, quotationsExpired: 0, sessionsPurged: 0, ms: 0 };
  try {
    const b = await runBillingDetailed(db, asOf, actor2);
    out.created = b.created;
    out.closed = b.closed;
    if (billing2.autoConfirm) {
      const drafts = await db.query("SELECT id FROM invoices WHERE status = 'draft' AND kind = 'recurring' AND invoice_date <= ? ORDER BY id", [asOf]);
      for (const d of drafts) {
        await confirmInvoice(db, d.id, actor2);
        out.confirmed += 1;
      }
    }
    if (billing2.autoSend) {
      const unsent = await db.query(`SELECT id FROM invoices WHERE status IN ('confirmed','paid') AND sent_at IS NULL AND kind <> 'credit_note'
        AND invoice_date <= ? ORDER BY id LIMIT 500`, [asOf]);
      for (const u of unsent) {
        await sendInvoice(db, u.id, opts.appUrl, actor2);
        out.sent += 1;
      }
    }
    const days = [...new Set(billing2.reminderDays.filter((d) => d > 0))].sort((a, b2) => a - b2);
    if (days.length) {
      const overdue = await db.query(`SELECT id, (?::date - due_date) AS late, reminder_count FROM invoices
        WHERE status = 'confirmed' AND kind <> 'credit_note' AND due_date < ? AND (last_reminder_at IS NULL OR last_reminder_at::date < ?::date)
        ORDER BY due_date LIMIT 500`, [asOf, asOf, asOf]);
      for (const inv of overdue) {
        const owedReminders = days.filter((d) => inv.late >= d).length;
        if (owedReminders > inv.reminder_count) {
          await remindInvoice(db, inv.id, opts.appUrl, actor2);
          out.reminders += 1;
        }
      }
    }
    if (billing2.dunningCloseDays > 0) {
      const reason = await db.prepare("SELECT id FROM close_reasons WHERE name = 'Unpaid invoices'").get();
      const subs = await db.query(`SELECT s.id, s.number, sum(i.total - i.amount_paid) AS owed FROM subscriptions s
        JOIN invoices i ON i.subscription_id = s.id AND i.status = 'confirmed' AND i.kind <> 'credit_note' AND i.due_date <= ?::date - ?::int
        WHERE s.status IN ('active','paused') GROUP BY s.id`, [asOf, billing2.dunningCloseDays]);
      for (const s of subs) {
        await applySubscriptionAction(db, s.id, "close", actor2, { reasonId: reason?.id ?? null, note: `Closed automatically: ${formatMoney(s.owed)} unpaid for over ${billing2.dunningCloseDays} days` }).then(() => {
          out.dunningClosed += 1;
        }).catch(() => void 0);
      }
    }
    if (billing2.renewalReminderDays > 0) {
      const ending = await db.query(`SELECT s.id, s.number, s.expiry_date, c.name, c.email, c.id AS customer_id
        FROM subscriptions s JOIN customers c ON c.id = s.customer_id JOIN plans p ON p.id = s.plan_id
        WHERE s.status = 'active' AND p.renewable = 1 AND s.expiry_date = ?::date + ?::int`, [asOf, billing2.renewalReminderDays]);
      for (const s of ending) {
        const already = await db.prepare("SELECT 1 FROM activity WHERE entity = 'subscription' AND entity_id = ? AND type = 'subscription.renewal_reminder' AND created_at::date = ?::date").get(s.id, asOf);
        if (already) continue;
        await sendMail(
          db,
          s.email,
          `${s.number} ends on ${s.expiry_date}`,
          `Hello ${s.name},

Your subscription ${s.number} ends on ${s.expiry_date}. Renew it from your portal to keep using it without a break:
${opts.appUrl}/portal/subscriptions/${s.id}
`,
          "renewal"
        );
        await logActivity(db, { type: "subscription.renewal_reminder", entity: "subscription", entityId: s.id, customerId: s.customer_id, actor: actor2, message: `Renewal reminder sent for ${s.number} (ends ${s.expiry_date}).` });
        out.renewalReminders += 1;
      }
    }
    const stale = await db.query("SELECT id FROM subscriptions WHERE status = 'quotation' AND valid_until < ?::date - 30", [asOf]);
    for (const q of stale) {
      const reason = await db.prepare("SELECT id FROM close_reasons WHERE name = 'Quotation expired'").get();
      await applySubscriptionAction(db, q.id, "close", actor2, { reasonId: reason?.id ?? null, note: "Quotation expired over 30 days ago" });
      out.quotationsExpired += 1;
    }
    out.sessionsPurged = (await db.prepare("DELETE FROM sessions WHERE expires_at < now()").run()).changes;
    await db.query("DELETE FROM password_resets WHERE expires_at < now() - interval '1 day'");
    await db.query("DELETE FROM rate_limits WHERE window_start < now() - interval '1 day'");
    await db.query("UPDATE checkouts SET status = 'expired' WHERE status = 'pending' AND created_at < now() - interval '1 day'");
    await db.query("DELETE FROM activity WHERE created_at < now() - interval '400 days'");
    out.ms = Math.round(performance.now() - started);
    await db.query("UPDATE job_runs SET finished_at = now(), ok = 1, summary = ?::jsonb WHERE id = ?", [JSON.stringify(out), run.lastInsertRowid]);
    await logActivity(db, {
      type: "automation.daily",
      entity: "billing",
      actor: actor2,
      message: `Daily automation for ${asOf}: ${out.created} invoices created, ${out.confirmed} confirmed, ${out.sent} sent, ${out.reminders} reminders, ${out.closed + out.dunningClosed} subscriptions closed.`,
      data: { ...out }
    });
    return out;
  } catch (e) {
    await db.query("UPDATE job_runs SET finished_at = now(), ok = 0, summary = ?::jsonb WHERE id = ?", [JSON.stringify({ ...out, error: e.message }), run.lastInsertRowid]);
    throw e;
  }
}
async function lastRuns(db, limit = 10) {
  return db.query(`SELECT id, job, triggered_by AS "trigger", started_at AS "startedAt", finished_at AS "finishedAt", ok, summary FROM job_runs ORDER BY id DESC LIMIT ?`, [limit]);
}

